notes.body:
This MR addresses reassembled packets that are retransmitted, or OOO. If the L5 dissected info is in a single packet, this behavior does not exist. The retransmitted in a single packet (not multiple PDU's), dissects above L4.

1st packet: reassembled and shown as "server hello"
![image](/uploads/a6e9f5e1b5d0e49d823000010f59ba8e/image.png){width=836 height=204}

2nd packet: The retransmit of the 1st packet, but the current code stops the dissector at TCP
![image](/uploads/c6f7c7adeb92db3616b5609013e2afa7/image.png){width=836 height=204}

This MR creates an option to dissect a reassembled packet above L4
![image](/uploads/cb8d3f49234f1aaf7457c128ed7cd3f7/image.png){width=900 height=515}

changes_data.diff:
@@ -550,6 +550,11 @@ static expert_field ei_mptcp_mapping_missing;
  */
 static bool tcp_no_subdissector_on_error = true;

+/* When enabled, retransmitted segments (including capture-level duplicates
+ * that fit inside an already-known multi-segment PDU) are still handed to
+ * the upper-layer dissector. Off by default to preserve existing behavior. */
+static bool tcp_dissect_retransmission_payload = false;
+
 /* Enable buffering of out-of-order TCP segments before passing it to a
  * subdissector (depends on "tcp_desegment"). */
 static bool tcp_reassemble_out_of_order;
@@ -5132,6 +5137,16 @@ again:
                         "Retransmitted TCP segment data (%u byte%s)",
                         nbytes, plurality(nbytes, "", "s"));

+                    /* If the user opted in, dissect the entire segment (including
+                     * the old/overlap portion) as the upper-layer protocol. The
+                     * Info column already carries the [TCP Retransmission] marker
+                     * via col_prepend_fence_fstr. */
+                    if (tcp_dissect_retransmission_payload) {
+                        decode_tcp_ports(tvb, offset, pinfo, tree, sport, dport,
+                                         tcpd, tcpinfo);
+                        goto clean_exit;
+                    }
+
                     offset += nbytes;
                     seq = tcpd->ta->new_data_seq;
                     first_pdu = false;
@@ -5236,6 +5251,16 @@ again:
                 proto_tree_add_bytes_format(tcp_tree, hf_tcp_segment_data, tvb, offset,
                     nbytes, NULL, "%sTCP segment data (%u byte%s)", str, nbytes,
                     plurality(nbytes, "", "s"));
+                /* If the user opted in, also hand the segment's payload to the
+                 * upper-layer sub-dissector so the L5+ contents (e.g. TLS
+                 * Server Hello) still appear. The Info column already carries
+                 * the [TCP Retransmission] marker via the earlier
+                 * col_prepend_fence_fstr call in
+                 * tcp_sequence_number_analysis_print_retransmission(). */
+                if (tcp_dissect_retransmission_payload) {
+                    decode_tcp_ports(tvb, offset, pinfo, tree, sport, dport,
+                                     tcpd, tcpinfo);
+                }
                 goto clean_exit;
             }

@@ -5281,6 +5306,11 @@ again:
                     proto_tree_add_bytes_format(tcp_tree, hf_tcp_segment_data, tvb, offset,
                         nbytes, NULL, "%sTCP segment data (%u byte%s)", str, nbytes,
                         plurality(nbytes, "", "s"));
+                    /* Same opt-in behavior as the MSP-boundary skip above. */
+                    if (tcp_dissect_retransmission_payload) {
+                        decode_tcp_ports(tvb, offset, pinfo, tree, sport, dport,
+                                         tcpd, tcpinfo);
+                    }
                     goto clean_exit;
                 }
             }
@@ -11439,6 +11469,17 @@ proto_register_tcp(void)
         "Do not call any subdissectors for Retransmitted or OutOfOrder segments",
         &tcp_no_subdissector_on_error);

+    prefs_register_bool_preference(tcp_module, "dissect_retransmission_payload",
+        "Dissect retransmitted segment payload (Layer 5+)",
+        "When enabled, retransmitted or capture-duplicate TCP segments that "
+        "match an already-known multi-segment PDU are still passed to the "
+        "upper-layer dissector (TLS, HTTP, etc.) instead of being shown only "
+        "as \"Retransmitted TCP segment data\". The Info column is prefixed "
+        "with [TCP Retransmission]. May produce confusing output for stateful "
+        "protocols (DCE/RPC, some encryption schemes) that don't tolerate "
+        "replays.",
+        &tcp_dissect_retransmission_payload);
+
     prefs_register_bool_preference(tcp_module, "dissect_experimental_options_rfc6994",
         "TCP Experimental Options using the format of RFC 6994",
         "Assume TCP Experimental Options (253, 254) have an Experiment Identifier and use it for dissection",
